// Lecteur d'un cours commencé ou fini (onglet Study, propre à ChatonLM) : le
// parcours des paliers à gauche, puis une carte à la fois (largeur de
// lecture), sous un en-tête (titre, barre de progression animée, temps
// restant, série de bonnes réponses, menu « … ») ; « Ask a question » sous
// les cartes d'un palier ; « Generated by {model}. It can make mistakes. »
// en pied.
//
// La carte montrée (« position », clé choisie par la page, voir
// src/lib/study.ts) est enregistrée par study_progress à chaque changement
// et toutes les 15 s, avec le temps passé (compté seulement page visible et
// fenêtre active) ; à l'ouverture, reprise à la position enregistrée (cours
// relu en base à l'ouverture de la page, voir CoursePage). Au changement de
// carte, son titre prend le focus (jamais pris à un champ de saisie) et la
// zone revient en haut ; la nouvelle carte glisse (mouvement réduit : rien).

import { EllipsisHorizontalIcon, FireIcon } from "@heroicons/react/20/solid";
import { useQueryClient } from "@tanstack/react-query";
import { useNavigate } from "@tanstack/react-router";
import { useCallback, useEffect, useRef, useState } from "react";
import type { AppError } from "@/bindings/AppError";
import type { Course } from "@/bindings/Course";
import { ConfirmDialog } from "@/components/ConfirmDialog";
import { ContextMenu, type MenuItem } from "@/components/ContextMenu";
import { READING } from "@/components/study/ui";
import { isTextField } from "@/hooks/useCardKeys";
import { LevelPath } from "@/components/study/LevelPath";
import {
  ExampleCard,
  FinalWaitCard,
  IntroCard,
  LevelWaitCard,
  RecapCard,
  RemedyCard,
  SectionCard,
} from "@/components/study/LessonCards";
import { EndCard, ResultCard } from "@/components/study/Outcome";
import { QuestionCard } from "@/components/study/QuestionCard";
import { AskPanel } from "@/components/study/Tutor";
import {
  courseKey,
  forgetLevelStreams,
  refreshCourse,
  studyListKey,
} from "@/hooks/useStudy";
import { useT } from "@/i18n";
import {
  errorMessage,
  studyDelete,
  studyProgress,
  studyRegenerate,
  studySaveNotes,
} from "@/lib/ipc";
import {
  type Card,
  cardOf,
  courseProgress,
  currentStreak,
  INTRO,
  levelOfCard,
  levelStartKey,
  nextCard,
  reachable,
  resolvePosition,
  roundMinutes,
  secondsLeft,
  STREAK_SHOWN,
  StudyClock,
} from "@/lib/study";

/** Enregistrement de la position et du temps passé, en plus des changements. */
export const PROGRESS_INTERVAL_MS = 15_000;

export function CourseReader({
  course,
  initialPosition,
}: {
  course: Course;
  /** Carte à montrer d'abord (sinon la position enregistrée). */
  initialPosition: string | null;
}) {
  const t = useT();
  const [position, setPosition] = useState(
    () => initialPosition ?? resolvePosition(course, course.position || INTRO),
  );
  const positionRef = useRef(position);
  // Carte ouverte par une action qui vient de réussir (« Continue anyway ») :
  // montrée même si le cours lu, relu juste après, la dit encore
  // verrouillée (sinon l'introduction passerait un instant).
  const [opened, setOpened] = useState<string | null>(null);
  const [clock] = useState(() => new StudyClock(course.elapsedMs));
  const [elapsed, setElapsed] = useState(course.elapsedMs);
  const scrollRef = useRef<HTMLDivElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const courseId = course.id;

  const save = useCallback(() => {
    studyProgress(courseId, positionRef.current, clock.elapsed()).catch(
      (error: unknown) => {
        // Cours supprimé (menu « Delete course », ailleurs) : plus rien à
        // enregistrer en quittant sa page.
        if ((error as Partial<AppError> | null)?.kind === "notFound") return;
        console.error("Failed to save the progress:", error);
      },
    );
  }, [courseId, clock]);

  /**
   * Montre une carte (bouton, parcours, Entrée) et l'enregistre ;
   * `justOpened` : ouverte par une action réussie (voir `opened`).
   */
  const go = useCallback(
    (key: string, justOpened = false) => {
      positionRef.current = key;
      setPosition(key);
      setOpened(justOpened ? key : null);
      setElapsed(clock.elapsed());
      save();
    },
    [clock, save],
  );

  // Temps compté page visible et fenêtre active ; enregistré toutes les 15 s
  // et en quittant la page.
  useEffect(() => {
    const update = () =>
      clock.setActive(
        document.visibilityState === "visible" && document.hasFocus(),
      );
    update();
    window.addEventListener("focus", update);
    window.addEventListener("blur", update);
    document.addEventListener("visibilitychange", update);
    const timer = setInterval(save, PROGRESS_INTERVAL_MS);
    save();
    return () => {
      window.removeEventListener("focus", update);
      window.removeEventListener("blur", update);
      document.removeEventListener("visibilitychange", update);
      clearInterval(timer);
      clock.setActive(false);
      save();
    };
  }, [clock, save]);

  const known = cardOf(course, position);
  const shownKey =
    known && (reachable(course, known) || opened === position)
      ? position
      : resolvePosition(course, position);
  const card = cardOf(course, shownKey) ?? { key: INTRO, kind: "intro" };
  const next = nextCard(course, card.key);
  const onNext = next ? () => go(next.key) : null;
  const level = levelOfCard(card);

  // Carte changée (ou attente remplacée par la carte prête) : son titre
  // prend le focus (sauf depuis un champ de saisie), la zone revient en haut.
  const cardKind = card.kind;
  useEffect(() => {
    scrollRef.current?.scrollTo?.({ top: 0 });
    if (isTextField(document.activeElement)) return;
    cardRef.current
      ?.querySelector<HTMLElement>("[data-card-heading]")
      ?.focus({ preventScroll: true });
  }, [shownKey, cardKind]);

  return (
    <div className="flex min-h-0 flex-1">
      <LevelPath
        course={course}
        viewedLevel={level}
        viewingFinal={card.kind === "final" || card.kind === "finalWait"}
        go={go}
      />
      <div ref={scrollRef} className="min-w-0 flex-1 overflow-y-auto">
        <ReaderHeader course={course} position={shownKey} go={go} />
        <div className={`${READING} flex flex-col gap-6 px-6 pb-6`}>
          <div
            ref={cardRef}
            key={card.key}
            className="motion-safe:animate-study-card-in"
          >
            <CardView
              course={course}
              card={card}
              next={next}
              onNext={onNext}
              go={go}
              elapsed={elapsed}
            />
          </div>
          {level !== null && course.levels[level]?.lesson && (
            <AskPanel
              key={`ask-${level}`}
              course={course}
              level={course.levels[level]}
            />
          )}
          <p className="text-center text-xs text-neutral-500">
            {t("study.reader.footer", { model: course.model })}
          </p>
        </div>
      </div>
    </div>
  );
}

function CardView({
  course,
  card,
  next,
  onNext,
  go,
  elapsed,
}: {
  course: Course;
  card: Card;
  next: Card | null;
  onNext: (() => void) | null;
  go: (key: string, justOpened?: boolean) => void;
  elapsed: number;
}) {
  const t = useT();
  switch (card.kind) {
    case "intro":
      return <IntroCard course={course} onNext={onNext} />;
    case "section":
      return (
        <SectionCard
          course={course}
          level={course.levels[card.level]}
          section={card.section}
          onNext={onNext}
        />
      );
    case "example":
      return (
        <ExampleCard
          course={course}
          level={course.levels[card.level]}
          onNext={onNext}
        />
      );
    case "recap":
      return (
        <RecapCard
          course={course}
          level={course.levels[card.level]}
          onNext={onNext}
        />
      );
    case "check":
      return (
        <QuestionCard
          course={course}
          question={card.question}
          eyebrow={t("study.question.practice")}
          onContinue={onNext}
        />
      );
    case "explain":
      return (
        <RemedyCard
          course={course}
          level={course.levels[card.level]}
          attempt={card.attempt}
          onNext={onNext}
        />
      );
    case "question":
      return (
        <QuestionCard
          course={course}
          question={card.question}
          eyebrow={t("study.question.checkpoint", {
            current: card.index + 1,
            total: card.total,
          })}
          onContinue={onNext}
          continueLabel={
            card.index + 1 === card.total
              ? t("study.question.seeResult")
              : undefined
          }
        />
      );
    case "result":
      return (
        <ResultCard
          course={course}
          level={course.levels[card.level]}
          attempt={card.attempt}
          next={next}
          go={go}
        />
      );
    case "levelWait":
      return (
        <LevelWaitCard course={course} level={course.levels[card.level]} />
      );
    case "final":
      return (
        <QuestionCard
          course={course}
          question={card.question}
          eyebrow={t("study.final.progress", {
            current: card.index + 1,
            total: card.total,
          })}
          onContinue={onNext}
        />
      );
    case "finalWait":
      return <FinalWaitCard course={course} />;
    case "end":
      return <EndCard course={course} elapsedMs={elapsed} />;
  }
}

/**
 * En-tête du lecteur : titre du cours, série de bonnes réponses (dès 3),
 * temps restant, menu ; barre de progression (cartes faites).
 */
function ReaderHeader({
  course,
  position,
  go,
}: {
  course: Course;
  position: string;
  go: (key: string) => void;
}) {
  const t = useT();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const menuButton = useRef<HTMLButtonElement>(null);
  const [menu, setMenu] = useState<{ x: number; y: number } | null>(null);
  const [confirm, setConfirm] = useState<"regenerate" | "delete" | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const { done, total } = courseProgress(course, position);
  const percent = total > 0 ? Math.round((done / total) * 100) : 0;
  const streak = currentStreak(course);
  const finished = course.status === "finished";
  const levelMatch = /^L(\d+):/.exec(position);
  const level = levelMatch ? Number(levelMatch[1]) : null;
  const canReport =
    level !== null && course.levels[level]?.state === "ready" && !finished;

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(null), 3000);
    return () => clearTimeout(timer);
  }, [notice]);

  const items: MenuItem[] = [];
  if (canReport) {
    items.push({
      label: t("study.menu.report"),
      onSelect: () => setConfirm("regenerate"),
    });
  }
  items.push({
    label: t("study.menu.saveNotes"),
    onSelect: () => {
      setError(null);
      studySaveNotes(course.id).then(
        (saved) => {
          if (saved) setNotice(t("study.end.saved"));
        },
        (cause: unknown) => setError(errorMessage(cause)),
      );
    },
  });
  items.push({
    label: t("study.menu.delete"),
    onSelect: () => setConfirm("delete"),
  });

  const openMenu = () => {
    const box = menuButton.current?.getBoundingClientRect();
    setMenu({ x: box ? box.right - 200 : 0, y: box ? box.bottom + 4 : 0 });
  };

  const regenerate = () => {
    setConfirm(null);
    if (level === null) return;
    setError(null);
    studyRegenerate(course.id, level).then(
      () => {
        // Explications et réponses de l'ancienne leçon : plus montrées.
        forgetLevelStreams(course.id, level);
        go(levelStartKey(level));
        refreshCourse(queryClient, course.id);
      },
      (cause: unknown) => setError(errorMessage(cause)),
    );
  };
  const remove = () => {
    setConfirm(null);
    setError(null);
    studyDelete(course.id).then(
      () => {
        queryClient.removeQueries({ queryKey: courseKey(course.id) });
        void queryClient.invalidateQueries({ queryKey: studyListKey });
        void navigate({ to: "/study" });
      },
      (cause: unknown) => setError(errorMessage(cause)),
    );
  };

  return (
    <header className="sticky top-0 z-10 bg-white px-6 pt-2 pb-4 dark:bg-neutral-900">
      <div className={`${READING} flex flex-col gap-2`}>
        <div className="flex items-center gap-3">
          <h2 className="min-w-0 flex-1 truncate font-rounded text-lg font-semibold text-neutral-900 dark:text-white">
            {course.plan?.title ?? course.topic}
          </h2>
          {streak >= STREAK_SHOWN && (
            <span
              data-testid="study-streak"
              className="flex flex-none items-center gap-1 rounded-full bg-amber-50 px-2 py-0.5 text-xs font-semibold text-amber-700 dark:bg-amber-950/40 dark:text-amber-300"
              title={t("study.reader.streak", { count: streak })}
            >
              <FireIcon
                aria-hidden="true"
                className="h-4 w-4 text-amber-500 motion-safe:animate-study-flame"
              />
              <span aria-hidden="true">{streak}</span>
              <span className="sr-only">
                {t("study.reader.streak", { count: streak })}
              </span>
            </span>
          )}
          <span className="flex-none text-xs text-neutral-500 dark:text-neutral-400">
            {finished
              ? t("study.reader.finished")
              : t("study.reader.timeLeft", {
                  count: roundMinutes(secondsLeft(course)),
                })}
          </span>
          <button
            ref={menuButton}
            type="button"
            className="flex-none rounded-full p-1.5 text-neutral-500 outline-none hover:bg-neutral-100 hover:text-neutral-900 focus-visible:ring-2 focus-visible:ring-accent-fg dark:hover:bg-neutral-800 dark:hover:text-white"
            aria-label={t("study.menu.label")}
            title={t("study.menu.label")}
            aria-haspopup="menu"
            aria-expanded={menu !== null}
            onClick={openMenu}
          >
            <EllipsisHorizontalIcon aria-hidden="true" className="h-5 w-5" />
          </button>
        </div>
        <div
          role="progressbar"
          aria-label={t("study.reader.progress")}
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={percent}
          aria-valuetext={t("study.reader.progressText", { done, total })}
          className="h-1.5 overflow-hidden rounded-full bg-neutral-200 dark:bg-neutral-800"
        >
          <div
            className={`h-full rounded-full transition-[width] duration-700 ease-out motion-reduce:transition-none ${finished ? "bg-emerald-500" : "bg-accent"}`}
            style={{ width: `${percent}%` }}
          />
        </div>
        {(notice || error) && (
          <p
            role={error ? "alert" : "status"}
            className={`text-xs ${error ? "text-red-600 dark:text-red-400" : "text-emerald-700 dark:text-emerald-400"}`}
          >
            {error ?? notice}
          </p>
        )}
      </div>
      {menu && (
        <ContextMenu
          x={menu.x}
          y={menu.y}
          items={items}
          onClose={() => setMenu(null)}
        />
      )}
      {confirm === "regenerate" && level !== null && (
        <ConfirmDialog
          title={t("study.report.title")}
          message={t("study.report.message")}
          confirmLabel={t("study.report.confirm")}
          onConfirm={regenerate}
          onCancel={() => setConfirm(null)}
        />
      )}
      {confirm === "delete" && (
        <ConfirmDialog
          title={t("study.delete.title", {
            title: course.plan?.title ?? course.topic,
          })}
          message={t("study.delete.message")}
          confirmLabel={t("common.actions.delete")}
          onConfirm={remove}
          onCancel={() => setConfirm(null)}
        />
      )}
    </header>
  );
}
